import { CUSTOMER_ACTIONS } from './actions'

export const INITIAL_STATE = {

}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case CUSTOMER_ACTIONS.GET_CUSTOMER_APPLICATION_DETAIL:
    case CUSTOMER_ACTIONS.UPDATE_CUSTOMER_APPLICATION:
    case CUSTOMER_ACTIONS.GET_DOWNLOAD_PDF:
    case CUSTOMER_ACTIONS.SUBMIT_CUSTOMER_POLICY:
    case CUSTOMER_ACTIONS.GET_FWD_TNC_URL:
    case CUSTOMER_ACTIONS.GET_CUSTOMER_DRAFT_QUOTE_DETAIL:
    case CUSTOMER_ACTIONS.UPDATE_CUSTOMER_DRAFT_QUOTE:
    case CUSTOMER_ACTIONS.COMPLETE_CUSTOMER_DRAFT:
      return {
        ...state,
        ...payload
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
