import { useEffect, useState } from 'react'
import { AccordionWrapper, AccordionHeading } from './index.style.js'
import Accordion from './TravelAccordian.js'

const QuoateAccordionComponent = ({ data = [], title = '' }) => {
  const [accData, setAccData] = useState([])

  useEffect(() => {
    const updatedData = data.map(( curr) => {
        return {title: Object.keys(curr)[0], data: Object.values(curr)[0]}
    })
    setAccData(updatedData)
  }, [data])
  return (
      <AccordionWrapper>
        <AccordionHeading>
          {title}
        </AccordionHeading>
        {data && accData.map((item, index) => {
          return (
            <>
               <Accordion index={index} title={item.title} data={item.data} parentTitle={title}/>
              
            </>
          )
        })}
      </AccordionWrapper>
  )
}
export default QuoateAccordionComponent
