import { createContext, useContext, useReducer } from 'react'

export const TravelContext = createContext()

export const TravelContextProvider = ({ reducer, ...props }) => {
  return (
    <TravelContext.Provider value={useReducer(reducer, {})}>
      {props.children}
    </TravelContext.Provider>
  )
}

export const useTravelContextValue = () => useContext(TravelContext)
