export const CUSTOMER_NOTE = [
  'Pengajuan via online',
  'Layanan Call Center 24 jam',
  'Apabila terdapat perbedaan data pada penawaran (QS) dengan sertifikat polis (SCP), maka akan mengacu kepada regulasi OJK.',
]

function PolicyDocumentDetails() {
  const { id } = useParams()
  const history = useHistory()
  const [{ getDownloadTravelDraftPdfData = {} }, getTravelDraftDownloadPdfReq] =
    useGetTravelDraftDownloadPdfReq()
  const [{ getDownloadTravelDraftPdfStatus }, dispatchError] = useErrorContextValue()
  const [{ getCustomerDraftQuoteDetailData = {} }, getCustomerDraftQuoteDetailReq] =
    useGetCustomerTravelDetails()

  useEffect(() => {
    if (id) {
      getCustomerDraftQuoteDetailReq({ draftQuoteId: id })
    }
  }, [getCustomerDraftQuoteDetailReq, id])

  useEffect(() => {
    if (getDownloadTravelDraftPdfStatus === 'success' && getDownloadTravelDraftPdfData) {
      downloadFile(getDownloadTravelDraftPdfData.pdf_url)
      dispatchError(
        resetError({
          getDownloadTravelDraftPdfStatus: '',
        })
      )
    }
  }, [getDownloadTravelDraftPdfStatus, getDownloadTravelDraftPdfData, dispatchError])

  const benefitsData = getCustomerDraftQuoteDetailData?.policy_details?.package_data?.benefit_list

  const handleBuyInsuranceNow = () => {
    if (getCustomerDraftQuoteDetailData?.section === 'mv_quote_summary') {
      history.push({
        pathname: `/customer/waiting/${id}`,
      })
    } else {
      history.push({
        pathname: `/travel/registration/${id}`,
      })
    }
  }

  const handleDownloadPdf = () => {
    console.log('id', id)
    if (id) {
      getTravelDraftDownloadPdfReq({
        draftQuoteId: id,
      })
    }
  }

  const renderProfileCards = (list, title) => {
    return (
      <>
        <CustomText
          color={AgentColorPallette.black}
          weight={700}
          size="15px"
          bottom="10px"
          top="20px"
        >
          {title}
        </CustomText>
        <ProfileContentCol>
          <Grid gridColumn="1fr 1fr" gridGap="space-between" className="action-grid">
            {list.map((item, index) => (
              <ProfileItemStyle border={index + 1 !== list?.length} key={index}>
                <DisplayFlexCCC
                  className="align-items-start"
                  // align={'start'}
                >
                  <CustomText
                    textAlign="start"
                    color={AgentColorPallette.fontGrey}
                    weight={400}
                    size="13px"
                    bottom="0"
                    paddingTop={'10px'}
                  >
                    {item.name}
                  </CustomText>
                  <CustomText
                    textAlign="start"
                    color={AgentColorPallette.black}
                    weight={400}
                    size="13px"
                    bottom="0"
                    paddingTop={'5px'}
                  >
                    {item.value}
                  </CustomText>
                </DisplayFlexCCC>
              </ProfileItemStyle>
            ))}
          </Grid>
        </ProfileContentCol>
      </>
    )
  }

  const renderProfileAgCards = (list, title) => {
    return (
      <>
        <CustomText
          color={AgentColorPallette.goldYellow}
          weight={700}
          size="15px"
          bottom="10px"
          top="20px"
        >
          {title}
        </CustomText>
        <ProfileContentCol>
          <Grid gridColumn="1fr 1fr" gridGap="space-between" className="action-grid">
            {list.map((item, index) => (
              <ProfileItemStyle border={index + 1 !== list?.length} key={index}>
                <DisplayFlexCCC
                  className="align-items-start"
                  // align={'start'}
                >
                  <CustomText
                    textAlign="start"
                    color={AgentColorPallette.fontGrey}
                    weight={400}
                    size="13px"
                    bottom="0"
                    paddingTop={'10px'}
                  >
                    {item.name}
                  </CustomText>
                  <CustomText
                    textAlign="start"
                    color={AgentColorPallette.black}
                    weight={400}
                    size="13px"
                    bottom="0"
                    paddingTop={'5px'}
                  >
                    {item.value}
                  </CustomText>
                </DisplayFlexCCC>
              </ProfileItemStyle>
            ))}
          </Grid>
        </ProfileContentCol>
      </>
    )
  }

  return (
    <div>
      <MitraHeaderStyle>
        <DisplayFlexRCSB className="mitra-header" justify={'space-between'}>
          <img className="pp-logo" src={NEW_LOGO_PP} alt="Logo Header" />
          <CustomText color={AgentColorPallette.black} size="11px" weight={800} bottom="0">
            {LANG_STRINGS.attachmentOffer}
          </CustomText>
        </DisplayFlexRCSB>
      </MitraHeaderStyle>
      <Wrapper>
        <Row className="" justify={'space-between'} padding={'50px'}>
          <WrapContent1>
            <DisplayFlexCCC align={'start'}>
              <CustomText weight={600} size="14px" color={AgentColorPallette.goldYellow}>
                {'No. Penawaran'}
              </CustomText>
              <CustomText weight={800} size="16px" color={AgentColorPallette.black}>
                {`PPMITRA-${getCustomerDraftQuoteDetailData?.id}`}
              </CustomText>
            </DisplayFlexCCC>
          </WrapContent1>
          <WrapContent2>
            <Row justify={'space-between'}>
              <img
                src={getCustomerDraftQuoteDetailData?.policy_details?.package_data?.logo_url}
                width={30}
                height={30}
                alt="logo"
                className="logo-image"
              />
              <DisplayFlexCCC align={'start'}>
                <CustomText size="0.75em" color={AgentColorPallette.fontDarkerGrey}>
                  {getCustomerDraftQuoteDetailData?.policy_details?.package_data?.name}
                </CustomText>
                <CustomText
                  size="0.9em"
                  weight={700}
                  bottom="0.8rem"
                  color={AgentColorPallette.blackGrey}
                >
                  {'Asuransi Perjalanan'}
                </CustomText>
              </DisplayFlexCCC>
            </Row>
          </WrapContent2>
        </Row>
      </Wrapper>
      <Hr />
      <Wrapper>
        <Row>
          <DisplayFlexCCC align={'start'}>
            <CustomText
              weight={700}
              size="1em"
              color={AgentColorPallette.goldYellow}
              className="align-items-start"
            >
              {'Ditujukan Ke'}
            </CustomText>
            <CustomText weight={800} size="15px" color={AgentColorPallette.black} lineHeight="18px">
              {'Kantor Pusat Asuransi Untuk Semua'}
            </CustomText>
            <CustomText weight={400} size="13px" color={AgentColorPallette.black} lineHeight="18px">
              {
                'One Pacific Place, 10th Floor unit D-H, SCBD Jl. Jend. Sudirman Kav 52-53, Jakarta Selatan 12190'
              }
            </CustomText>
          </DisplayFlexCCC>
        </Row>
        <Hr />
        {renderProfileAgCards(
          getProductDetails(getCustomerDraftQuoteDetailData),
          'Detail Perlindungan'
        )}
        <Hr />
        {renderProfileAgCards(getAgentDetails(getCustomerDraftQuoteDetailData), 'Data Agen')}
        <Hr />
        <QuoateAccordionComponent data={benefitsData} title="Daftar Manfaat" />
        <Hr />
        <div>
          <CustomText weight={700} size="16px" color={AgentColorPallette.goldYellow}>
            {'Perhitungan Premi'}
          </CustomText>
          <DisplayFlexRow>
            <PremiumnCal>Premi Dasar</PremiumnCal>
            {/* <PremiumnCal>{`IDR ${getTravelDetailsData?.policy_details?.package_data?.basic_premium}`}</PremiumnCal> */}
            <PremiumnCal>
              {formatMoney(
                getCustomerDraftQuoteDetailData?.policy_details?.package_data?.basic_premium,
                0,
                'IDR'
              )}
            </PremiumnCal>
          </DisplayFlexRow>
          {/* <DisplayFlexRow>
            <PremiumnCal>Perlindungan Tambahan</PremiumnCal>
            <PremiumnCal>Perlindungan Tambahan</PremiumnCal>
          </DisplayFlexRow> */}
          <DisplayFlexRow>
            <SubTotalCal>Subtotal</SubTotalCal>
            <SubTotalCal>
              {formatMoney(
                getCustomerDraftQuoteDetailData?.policy_details?.package_data?.sub_total,
                0,
                'IDR'
              )}
            </SubTotalCal>
          </DisplayFlexRow>
          <DisplayFlexRow>
            <PremiumnCal>Biaya Materai</PremiumnCal>
            <PremiumnCal>
              {formatMoney(
                getCustomerDraftQuoteDetailData?.policy_details?.package_data?.stamp_duty,
                0,
                'IDR'
              )}
            </PremiumnCal>
          </DisplayFlexRow>
          <DisplayFlexRow>
            <PremiumnCal>Diskon</PremiumnCal>
            <PremiumnCal>
              {formatMoney(getCustomerDraftQuoteDetailData?.policy_details?.discount, 0, 'IDR')}
            </PremiumnCal>
          </DisplayFlexRow>
          <DisplayFlexRow>
            <TotalPreCal>Total Premi</TotalPreCal>
            <TotalPreCal>
              {formatMoney(
                getCustomerDraftQuoteDetailData?.policy_details?.package_data?.total_bill,
                0,
                'IDR'
              )}
            </TotalPreCal>
          </DisplayFlexRow>
        </div>
      </Wrapper>
      <TotalPreCalDiv>
        <TotalPreCal2>Total Premi</TotalPreCal2>
        <TotalPreCal3>
          {formatMoney(
            getCustomerDraftQuoteDetailData?.policy_details?.package_data?.total_bill,
            0,
            'IDR'
          )}
        </TotalPreCal3>
      </TotalPreCalDiv>
      <CustomerNoteStyle>
        <CustomText color={AgentColorPallette.black} bottom="4px">
          {LANG_STRINGS.note}:
        </CustomText>
        {CUSTOMER_NOTE.map((note, index) => (
          <CustomText
            key={`note_${index}`}
            color={AgentColorPallette.black}
            bottom="4px"
            lineHeight={1.5}
          >
            {`${index + 1}. ${note}`}
          </CustomText>
        ))}
      </CustomerNoteStyle>
      <Footer>
        <CustomText weight="700" size="9px" textAlign="center" color="#000000">
          {LANG_STRINGS.OjkText}
        </CustomText>
        <img src={OJK_PP_BLACK} className="ojk-logo" alt="logo" />
      </Footer>
      <BtnContainerStyle>
        <BtnCustomerPolicyStyle
          justify="space-between"
          align="center"
          onClick={handleDownloadPdf}
          flex={'auto'}
          backgroundColor={AgentColorPallette.black}
        >
          <CustomText color={AgentColorPallette.white} size="14px" weight={800}>
            {LANG_STRINGS.downloadFile}
          </CustomText>
          <img src={DOWNLOAD_WHITE} alt="" />
        </BtnCustomerPolicyStyle>
        <BtnCustomerPolicyStyle
          justify="space-between"
          align="center"
          position={'relative'}
          onClick={handleBuyInsuranceNow}
          flex={'auto'}
          backgroundColor={AgentColorPallette.primary}
        >
          <CustomText color={AgentColorPallette.black} size="14px" weight={800}>
            {LANG_STRINGS.buyInsurance}
          </CustomText>
          <img src={BLACK_PLANE} alt="" />
        </BtnCustomerPolicyStyle>
      </BtnContainerStyle>
    </div>
  )
}

export default PolicyDocumentDetails
