import { useState } from "react";
import {
  AccordionItems,
  AccordionTitle,
  AccordionData,
  ArrowWrapper,
  AccDetailKey,
} from "./index.style";

const Accordion = ({ title, data = [], parentTitle, index }) => {
  const [isActive, setIsActive] = useState(true);

  const renderComponent = (acc, index) => {
      const title = Object.keys(acc)[0];
      return (
        <AccordionData>
          <AccDetailKey>{`${index + 1}. ${title}`} </AccDetailKey>    
             
        </AccordionData>
      );
    
  };

  return (
    <AccordionItems>
      <AccordionTitle onClick={() => setIsActive(!isActive)}>
        {`${String.fromCharCode(65 + index)}. ${title}`}
        <ArrowWrapper>
          {isActive ? (
            <i className="fas fa-angle-up" />
          ) : (
            <i className="fas fa-angle-down" />
          )}
        </ArrowWrapper>
      </AccordionTitle>
      {isActive && data.length && data?.map((acc, index) => renderComponent(acc, index))}
    </AccordionItems>
  );
};
export default Accordion;
